using Microsoft.EntityFrameworkCore;
using UsedCarSales.Api.Models;
namespace UsedCarSales.Api.Data;
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) { public DbSet<Car> Cars => Set<Car>(); public DbSet<Customer> Customers => Set<Customer>(); public DbSet<Sale> Sales => Set<Sale>(); public DbSet<Billing> Billings => Set<Billing>(); protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.Entity<Car>().HasIndex(x => x.StockNumber).IsUnique(); modelBuilder.Entity<Car>().Property(x => x.Price).HasPrecision(12,2); modelBuilder.Entity<Sale>().Property(x => x.SalePrice).HasPrecision(12,2); modelBuilder.Entity<Sale>().Property(x => x.Discount).HasPrecision(12,2); modelBuilder.Entity<Sale>().Property(x => x.TaxRate).HasPrecision(5,4); modelBuilder.Entity<Billing>().Property(x => x.TotalAmount).HasPrecision(12,2); modelBuilder.Entity<Billing>().Property(x => x.Subtotal).HasPrecision(12,2); modelBuilder.Entity<Billing>().Property(x => x.Discount).HasPrecision(12,2); modelBuilder.Entity<Billing>().Property(x => x.TaxAmount).HasPrecision(12,2); modelBuilder.Entity<Sale>().HasOne(x => x.Billing).WithOne(x => x.Sale).HasForeignKey<Billing>(x => x.SaleId); } }
